create table public.github_webhook_deliveries(delivery_id text primary key,event text not null,installation_id bigint,repository_id bigint,action text,signature_valid boolean not null,received_at timestamptz not null default now(),processed_at timestamptz,status text not null check(status in('received','processed','ignored','failed')),redacted_error jsonb);
create table public.github_sync_records(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,repository_id bigint not null,kind text not null check(kind in('commit','issue','pull_request','workflow','workflow_run','check','release','discussion')),github_id bigint not null,node_id text,revision text,state text,title text,source_url text,updated_at_provider timestamptz,last_observed_at timestamptz not null default now(),indexed_at timestamptz,deletion_at timestamptz,payload jsonb not null default '{}',unique(owner_id,repository_id,kind,github_id),foreign key(owner_id,repository_id) references public.github_repositories(owner_id,id) on delete cascade);
create table public.github_coding_selections(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,run_id uuid references public.agent_jobs(id) on delete cascade,chat_id text,repository_id bigint not null,branch text not null,issue_number integer,pr_number integer,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((run_id is null)<>(chat_id is null)),unique(owner_id,run_id),unique(owner_id,chat_id),foreign key(owner_id,repository_id) references public.github_repositories(owner_id,id));
alter table public.github_webhook_deliveries enable row level security;alter table public.github_sync_records enable row level security;alter table public.github_coding_selections enable row level security;
create policy "Owners read GitHub sync" on public.github_sync_records for select using(auth.uid()=owner_id and exists(select 1 from github_repositories r where r.id=repository_id and r.owner_id=github_sync_records.owner_id and r.owner_id=auth.uid() and r.explicitly_granted and r.revoked_at is null));create policy "Owners manage coding selections" on public.github_coding_selections for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id and exists(select 1 from github_repositories r where r.id=repository_id and r.owner_id=github_coding_selections.owner_id and r.owner_id=auth.uid() and r.explicitly_granted and r.revoked_at is null));
-- Webhook deliveries are service-only: no authenticated/anon policies.
